import { env } from 'node:process';
import { stashAsset } from './assets.js';
const DEFAULT_ASSET_CONCURRENCY = 4;
const DEFAULT_ASSET_TIMEOUT = 180;
const assetTimeoutS = Number(env.SANITY_ASSET_TIMEOUT) || DEFAULT_ASSET_TIMEOUT;
const assetTimeoutMs = assetTimeoutS * 1000;
const warnTimeoutMs = assetTimeoutMs / 3;
export async function processAssets(options) {
    const { assetResources, onProgress, onResult } = options;
    const total = assetResources.length;
    const processedAssets = [];
    const concurrency = getAssetConcurrency();
    let completed = 0;
    let slow = false;
    const reportProgress = () => onProgress?.({ completed, total, slow });
    reportProgress();
    const warnTimer = setTimeout(() => {
        slow = true;
        reportProgress();
    }, warnTimeoutMs);
    try {
        for (let start = 0; start < total; start += concurrency) {
            const batch = assetResources.slice(start, start + concurrency);
            const batchResults = await Promise.all(batch.map(async (resource) => {
                const result = await processAsset(resource, options);
                completed += 1;
                reportProgress();
                onResult?.(result);
                return result;
            }));
            processedAssets.push(...batchResults);
            if (batchResults.some((result) => !result.success))
                break;
        }
    }
    finally {
        clearTimeout(warnTimer);
    }
    return processedAssets;
}
function getAssetConcurrency() {
    const configured = Number(env.SANITY_ASSET_CONCURRENCY);
    return Number.isSafeInteger(configured) && configured > 0 ? configured : DEFAULT_ASSET_CONCURRENCY;
}
async function processAsset(resource, options) {
    const { auth, blueprintFileDir, installer, logger } = options;
    let assetTimeoutTimer;
    let result;
    try {
        result = await Promise.race([
            stashAsset({ resource, blueprintFileDir, auth, logger, installer }),
            new Promise((_, reject) => {
                assetTimeoutTimer = setTimeout(() => {
                    reject(new Error(`Processing ${resource.name} timed out after ${assetTimeoutS}s`));
                }, assetTimeoutMs);
            }),
        ]);
    }
    catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        return { success: false, resource, error: msg, failureKind: 'processing' };
    }
    finally {
        clearTimeout(assetTimeoutTimer);
    }
    if (result.success && result.assetId) {
        return {
            success: true,
            resource: { ...resource, src: result.assetId },
            hash: result.hash,
            exists: result.exists,
        };
    }
    return {
        success: false,
        resource,
        error: result.error || 'Failed to process asset',
        failureKind: 'upload',
    };
}
